package agent

import (
	"github.com/entireio/cli/cmd/entire/cli/agent/claudecode"
	"github.com/entireio/cli/cmd/entire/cli/agent/geminicli"
)

// CountTranscriptItems counts lines (JSONL) or messages (JSON) in a transcript.
// For Claude Code and JSONL-based agents, this counts lines.
// For Gemini CLI and JSON-based agents, this counts messages in the "messages" array.
// Returns 0 if the data is empty or malformed.
func CountTranscriptItems(agentType AgentType, data []byte) int {
	if len(data) == 0 {
		return 0
	}

	switch agentType {
	case AgentTypeGemini:
		transcript, err := geminicli.ParseTranscript(data)
		if err != nil || transcript == nil {
			return 0
		}
		return len(transcript.Messages)

	case AgentTypeClaudeCode:
		fallthrough
	default:
		// Claude Code and others use JSONL format
		lines, err := claudecode.ParseTranscript(data)
		if err != nil {
			return 0
		}
		return len(lines)
	}
}

// ExtractUserPrompts extracts all user prompts from transcript data.
// Returns prompts with IDE context tags stripped (e.g., <ide_opened_file>).
func ExtractUserPrompts(agentType AgentType, data []byte) ([]string, error) {
	if len(data) == 0 {
		return nil, nil
	}

	switch agentType {
	case AgentTypeGemini:
		return geminicli.ExtractAllUserPrompts(data)

	case AgentTypeClaudeCode:
		fallthrough
	default:
		// Claude Code and others use JSONL format
		lines, err := claudecode.ParseTranscript(data)
		if err != nil {
			return nil, err
		}
		prompt := claudecode.ExtractLastUserPrompt(lines)
		if prompt == "" {
			return nil, nil
		}
		// Note: For Claude Code, we only extract the last prompt here.
		// If full history is needed, could extract all user messages from lines.
		return []string{prompt}, nil
	}
}

// CalculateTokenUsageFromData calculates token usage from raw transcript data.
// startOffset is the line number (Claude Code) or message index (Gemini CLI) where the current checkpoint began.
// This allows calculating token usage for only the portion of the transcript since the last checkpoint.
func CalculateTokenUsageFromData(agentType AgentType, data []byte, startOffset int) *TokenUsage {
	if len(data) == 0 {
		return &TokenUsage{}
	}

	switch agentType {
	case AgentTypeGemini:
		return geminicli.CalculateTokenUsage(data, startOffset)

	case AgentTypeClaudeCode:
		fallthrough
	default:
		// Claude Code doesn't use startOffset - it calculates from full transcript
		lines, err := claudecode.ParseTranscript(data)
		if err != nil || len(lines) == 0 {
			return &TokenUsage{}
		}
		return claudecode.CalculateTokenUsage(lines)
	}
}

